using System;using System.IO;using System.Runtime.InteropServices;using System.Windows;using System.Windows.Interop;using System.Windows.Threading;
namespace DesktopBox {
// The only sampled key is F6. No keyboard hook or sampling of other keys.
public sealed class DockHold:IDisposable {
 [DllImport("user32.dll",SetLastError=true)]static extern bool RegisterHotKey(IntPtr window,int id,uint modifiers,uint key);
 [DllImport("user32.dll")]static extern bool UnregisterHotKey(IntPtr window,int id);
 [DllImport("user32.dll")]static extern short GetAsyncKeyState(int key);
 readonly System.Collections.Generic.Queue<string> transitions=new System.Collections.Generic.Queue<string>();readonly DockBar dock;readonly HwndSource source;readonly IntPtr handle;readonly DispatcherTimer release;readonly bool simulated;bool disposed;
 public bool Active{get{return !disposed&&(Registered||simulated);}}public bool Registered{get;private set;}public bool Held{get;private set;}public int Error{get;private set;}public int Presses{get;private set;}public int Releases{get;private set;}
 public DockHold(DockBar owner,bool test=false){dock=owner;simulated=test;handle=new WindowInteropHelper(dock).Handle;source=HwndSource.FromHwnd(handle);release=new DispatcherTimer(DispatcherPriority.Input,dock.Dispatcher){Interval=TimeSpan.FromMilliseconds(25)};release.Tick+=(o,e)=>{if((GetAsyncKeyState(0x75)&0x8000)==0)SetHeld(false,"F6 released");};if(!test){Registered=RegisterHotKey(handle,2,0x4000,0x75);if(!Registered)Error=Marshal.GetLastWin32Error();source.AddHook(Hook);Microsoft.Win32.SystemEvents.SessionSwitch+=SessionSwitch;}Record("initialized");}
 IntPtr Hook(IntPtr window,int message,IntPtr wp,IntPtr lp,ref bool handled){if(message==0x312&&wp.ToInt32()==2&&Registered){SetHeld(true,"WM_HOTKEY F6");handled=true;}return IntPtr.Zero;}
 void SessionSwitch(object sender,Microsoft.Win32.SessionSwitchEventArgs e){if(e.Reason==Microsoft.Win32.SessionSwitchReason.SessionLock||e.Reason==Microsoft.Win32.SessionSwitchReason.SessionLogoff||e.Reason==Microsoft.Win32.SessionSwitchReason.RemoteDisconnect)dock.Dispatcher.BeginInvoke(new Action(()=>SetHeld(false,"session inactive")));}
 public void SetHeld(bool value,string reason){if(disposed||(!Registered&&!simulated)||Held==value)return;Held=value;if(value){Presses++;if(!simulated)release.Start();}else{Releases++;release.Stop();}dock.ApplyHoldVisibility();Record(reason);}
 public void Record(string reason){try{var state=new{time=DateTimeOffset.Now.ToString("o"),key="F6",registered=Registered,error=Error,held=Held,Presses,Releases,reason,simulated,visible=dock.IsVisible,window=Native.WidgetInfo(dock),foreground=Native.GetForegroundWindow().ToInt64(),scope="F6 system hotkey; only F6 high-bit key state sampled while held; no keyboard hook or other key sampling; only last 16 F6 state transitions"};string json=new System.Web.Script.Serialization.JavaScriptSerializer().Serialize(state);File.WriteAllText(Path.Combine(Program.S.Root,"dock-f6-state.json"),json,System.Text.Encoding.UTF8);transitions.Enqueue(json);while(transitions.Count>16)transitions.Dequeue();File.WriteAllLines(Path.Combine(Program.S.Root,"dock-f6-transitions.jsonl"),transitions,System.Text.Encoding.UTF8);}catch{}}
 public void Dispose(){if(disposed)return;if(Held){Held=false;Releases++;if(dock.IsVisible)dock.ApplyHoldVisibility();}disposed=true;release.Stop();if(!simulated){if(!source.IsDisposed)source.RemoveHook(Hook);Microsoft.Win32.SystemEvents.SessionSwitch-=SessionSwitch;if(Registered)UnregisterHotKey(handle,2);}Registered=false;}
}
}
